// Wireless value index — record JAH-GPCS-WIFIBTCARD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"wifi_std_num": 7, "speed_mbps": 5800};
var value = (m.wifi_std_num*m.speed_mbps/1000);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-WIFIBTCARD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-WIFIBTCARD-000001|' + value.toFixed(2) + ' wireless index');

